	// Only a live repository fact shadows. The precedence above is justified by
	// the local copy being the more specific claim carrying checkable
	// provenance; a retracted or superseded fact makes no claim, so it has
	// nothing to shadow with. Letting it shadow anyway would mean retracting a
	// local duplicate silently removed the global statement from this one repo.
	seen := make(map[string]bool, len(repoFacts))
	for _, fact := range repoFacts {
		switch fact.Status {
		case "", factStatusActive:
			seen[fact.ID] = true
		}
	}
	merged := repoFacts
	globalIDs := map[string]bool{}
	for _, fact := range global {
		if seen[fact.ID] {
			continue
		}
		// A retracted or superseded global fact is filtered by the same code
		// that filters repository ones; nothing special happens here.
		merged = append(merged, fact)
		globalIDs[fact.ID] = true
	}
	return merged, globalIDs
}"},{"rank":2,"score":39.0657,"file_path":"internal/cli/agent_surface.go","start_line":1670,"end_line":1674,"focus_line":1672,"snippet_start_line":1670,"snippet_end_line":1674,"symbol_start_line":1369,"symbol_end_line":1884,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/agent_surface.go:function:runBrainBriefWithRawHistoryMatcher","symbol_name":"runBrainBriefWithRawHistoryMatcher","qualified_name":"runBrainBriefWithRawHistoryMatcher","signature":"func runBrainBriefWithRawHistoryMatcher(ctx context.Context, cmd *cobra.Command, opts Options, briefOpts brainBriefOptions, task string, rawHistoryMatcher brainBriefRawHistoryMatcher) error","signals":["body","signature","symbol-usage"],"snippet":"		} else {
