	if envBool(webhookIncludeTextEnv) {
		fact.Text = record.Text
	}
	return webhookEvent{
		Event:     name,
		Timestamp: now.UTC().Format(time.RFC3339),
		Repo:      repoName,
		Branch:    branch,
		Fact:      fact,
	}
}

